const DENY = new Set([
  'purchasePrice', 'purchaseAmount', 'hourlyCost', 'hiddenFeesPercentage',
  'birthDate', 'firebaseNotificationTokens', 'password', 'salt', 'confirmationCode',
  'emailSignature', 'lastConnectionDate', 'onboarding'
]);
function html2txt(s) {
  return s.replace(/<br\s*\/?>/gi, '\n').replace(/<\/p>/gi, '\n').replace(/<[^>]+>/g, '')
    .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
    .replace(/\n{2,}/g, '\n').trim();
}
function strip(v) {
  if (Array.isArray(v)) return v.map(strip);
  if (v && typeof v === 'object') {
    const o = {};
    for (const k of Object.keys(v)) {
      if (DENY.has(k)) continue;
      let val = v[k];
      if (k === 'name' && typeof val === 'string' && /<[a-z][^>]*>/i.test(val)) val = html2txt(val);
      o[k] = strip(val);
    }
    return o;
  }
  return v;
}
const CODES = {
  1: 'heure approximative (battement 15 a 30 min)',
  2: 'demi-journee',
  3: 'journee entiere',
  4: 'date non fixee (a caler)'
};
function enrich(ev) {
  const startRaw = ev && (ev.start || ev.startHour);
  if (!startRaw) return ev;
  const dt = DateTime.fromISO(startRaw, { zone: 'utc' }).setZone('Europe/Paris');
  const code = dt.minute % 10;
  ev.dateParis = dt.toISODate();
  ev.heureParis = dt.toFormat('HH:mm');
  ev.codeHoraire = code;
  ev.horaireLibelle = CODES[code] || 'heure fixe';
  if (Array.isArray(ev.users)) {
    const seen = new Set();
    ev.users = ev.users.filter(u => { if (!u || seen.has(u.id)) return false; seen.add(u.id); return true; });
    ev.technicianIds = ev.users.map(u => u.id);
  }
  ev.sousContrat = !!ev.maintenance;
  ev.secondReference = String(ev.secondReference || '').trim();
  return ev;
}
const res = $input.first().json;
const op = $('Resoudre endpoint').first().json.op;
const status = res.statusCode;
let body = res.body;
if (!(status >= 200 && status < 300)) {
  const msg = typeof body === 'string' ? body : JSON.stringify(body || {});
  return [{ json: { ok: false, op, statusCode: status, erreur: msg.slice(0, 300) } }];
}
body = strip(body);
if (body && Array.isArray(body.items) && (op === 'events_jour' || op === 'rdv_jour' || op === 'client_events')) body.items = body.items.map(enrich);
if (op === 'intervention') body = enrich(body);
return [{ json: { ok: true, op, statusCode: status, data: body } }];

const inp = $input.first().json;
const op = String(inp.op || '').trim();
const p = (inp.params && typeof inp.params === 'object') ? inp.params : {};
const BASE = 'https://app.inter-fast.fr';
const enc = encodeURIComponent;

function qs(obj) {
  const parts = [];
  for (const k of Object.keys(obj)) {
    const v = obj[k];
    if (v === undefined || v === null || v === '') continue;
    if (Array.isArray(v)) { const arr = v.length === 1 ? [v[0], v[0]] : v; for (const x of arr) parts.push(enc(k) + '=' + enc(x)); }
    else parts.push(enc(k) + '=' + enc(v));
  }
  return parts.length ? '?' + parts.join('&') : '';
}
function id(v, label) {
  const s = String(v || '').trim();
  if (!/^[A-Za-z0-9-]{1,64}$/.test(s)) throw new Error('Parametre ' + label + ' invalide ou manquant');
  return s;
}

let path = '';
let query = {};
switch (op) {
  case 'events_jour':
  case 'rdv_jour': {
    const d = p.date ? String(p.date) : DateTime.now().setZone('Europe/Paris').plus({ days: 1 }).toISODate();
    const day = DateTime.fromISO(d, { zone: 'Europe/Paris' });
    if (!day.isValid) throw new Error('Parametre date invalide (attendu AAAA-MM-JJ)');
    const n = Math.min(Math.max(parseInt(p.jours || 1, 10) || 1, 1), 31);
    query = {
      start: day.startOf('day').toUTC().toISO(),
      end: day.plus({ days: n - 1 }).endOf('day').toUTC().toISO(),
      page: 0, count: 100, archived: false, meeting: op === 'rdv_jour'
    };
    if (Array.isArray(p.technicianIds) && p.technicianIds.length) query.technicians = p.technicianIds.map(x => id(x, 'technicianIds'));
    else if (p.technicianId) query.technicians = [id(p.technicianId, 'technicianId')];
    path = '/v1/events';
    break;
  }
  case 'intervention': path = '/v1/intervention/' + id(p.id, 'id'); break;
  case 'client': path = '/v1/client/' + id(p.id, 'id'); break;
  case 'client_adresses': path = '/v1/client/' + id(p.id, 'id') + '/addresses'; break;
  case 'client_events': path = '/v1/client/' + id(p.id, 'id') + '/events'; query = { page: 0, count: 50 }; break;
  case 'client_activites': {
    const n = Math.min(Math.max(parseInt(p.taille || 30, 10) || 30, 1), 100);
    path = '/v1/client/' + id(p.id, 'id') + '/activities'; query = { page: 0, size: n };
    break;
  }
  case 'client_recherche': {
    const nom = String(p.nom || '').trim().slice(0, 60);
    if (nom.length < 2) throw new Error('Parametre nom trop court');
    path = '/v1/crm/search'; query = { name: nom, page: 0, size: 10, archived: false };
    break;
  }
  case 'devis': path = '/v1/billing/quotations/' + id(p.id, 'id'); break;
  case 'devis_par_ref': {
    const ref = String(p.ref || '').trim().toUpperCase();
    if (!/^[A-Z]{1,3}[0-9]{2,6}$/.test(ref)) throw new Error('Parametre ref invalide (attendu ex. DC4676)');
    path = '/v1/billing/quotations'; query = { name: ref, page: 0, size: 5 };
    break;
  }
  case 'devis_client_signes':
  case 'devis_client':
    path = '/v1/billing/quotations';
    query = { clients: [id(p.clientId, 'clientId')], page: 0, size: 20, orderBy: 'createdAt', isDesc: true };
    break;
  default:
    throw new Error('Operation non autorisee: "' + op + '" (lecture seule, liste blanche)');
}
return [{ json: { op, url: BASE + path + qs(query) } }];

